INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Breakpoints nur in Schleifen nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Überall im Code einsetzbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf Schleifen beschränkt"}]'),
