('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Breakpoints permanent sind?', 2, '[{"text": "Nein", "correct": true, "because": "Nur während Debugging"}, {"text": "Ja", "correct": false, "because": "Temporär aktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich für Breakpoints?', 3, '[{"text": "Debugger", "correct": true, "because": "Setzt und verwaltet sie"}, {"text": "Texteditor", "correct": false, "because": "Nur Anzeige"}, {"text": "Compiler", "correct": false, "because": "Übersetzt Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Breakpoints?', 5, '[{"text": "Fehlerlokalisierung", "correct": true, "because": "Zeigt Problemstellen"}, {"text": "Variablenkontrolle", "correct": true, "because": "Überprüft Zustände"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Leistungseffekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Breakpoints stoppen bei Bedingungen. b) Sie sind nur für große Programme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Auch kleine Programme"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Breakpoints?', 4, '[{"text": "Debugging-Tool", "correct": false, "because": "Setzt Breakpoints"}, {"text": "Codezeile", "correct": false, "because": "Definiert Stopp"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Breakpoints nur für Fehler?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Ablaufprüfung"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Möglichkeiten bieten Breakpoints?', 4, '[{"text": "Code pausieren", "correct": true, "because": "Stoppt Ausführung"}, {"text": "Variablen inspizieren", "correct": true, "because": "Zeigt Werte"}, {"text": "Daten komprimieren", "correct": false, "because": "Kein Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Breakpoints die Laufzeit erhöhen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur während Debugging"}, {"text": "Ja", "correct": false, "because": "Kein permanenter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Breakpoints?', 3, '[{"text": "Strategische Platzierung", "correct": true, "because": "Sichert Analyse"}, {"text": "Schnelle Aktivierung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
